import unicodedata
import hashlib
import hmac
import os
import re
from typing import Optional, Dict, Set

# Security: Rate limiting and session management
class RateLimiter:
    def __init__(self, max_requests: int = 100):
        self.max_requests = max_requests
        self.counts: Dict[str, int] = {}

    def check(self, user_id: str) -> bool:
        self.counts[user_id] = self.counts.get(user_id, 0) + 1
        return self.counts[user_id] <= self.max_requests

class FileVault:
    """Secure file storage with access control."""

    def __init__(self, base_dir: str, admin_token: str):
        self.base_dir = os.path.realpath(base_dir)
        self.admin_token = admin_token
        self.rate_limiter = RateLimiter()
        self.user_permissions: Dict[str, Set[str]] = {}
        self.blocked_names: Set[str] = set()
        self._load_blocked_names()

    def _load_blocked_names(self):
        """Load list of blocked filenames from config."""
        blocked = os.environ.get('VAULT_BLOCKED_FILES', '')
        for name in blocked.split(','):
            cleaned = name.strip().lower()
            if cleaned:
                self.blocked_names.add(cleaned)

    def _normalize_filename(self, filename: str) -> str:
        """Normalize filename for consistent handling."""
        # NFKC normalization - canonical decomposition + compatibility composition
        normalized = unicodedata.normalize('NFKC', filename)
        # Strip leading/trailing whitespace and dots
        normalized = normalized.strip().strip('.')
        return normalized

    def _validate_filename(self, filename: str) -> bool:
        """Security validation - check filename against blocklist."""
        # Use same NFKC normalization as _normalize_filename
        check_name = unicodedata.normalize('NFKC', filename)
        check_name = check_name.strip().strip('.').lower()

        # Block path traversal
        if '..' in check_name or '/' in check_name or '\\' in check_name:
            return False

        # Check against blocklist
        if check_name in self.blocked_names:
            return False

        # Block control characters
        if any(unicodedata.category(c).startswith('C') for c in check_name):
            return False

        return True

    def _check_path_safety(self, full_path: str) -> bool:
        """Ensure resolved path is within base directory."""
        real_path = os.path.realpath(full_path)
        return real_path.startswith(self.base_dir + os.sep) or real_path == self.base_dir

    def grant_access(self, admin_token: str, user_id: str, filename: str) -> bool:
        """Admin grants a user access to a specific file."""
        if not self._constant_time_compare(admin_token, self.admin_token):
            return False
        if user_id not in self.user_permissions:
            self.user_permissions[user_id] = set()
        # Store permission using NFKC-normalized name (matches all lookups)
        norm_name = self._normalize_filename(filename)
        self.user_permissions[user_id].add(norm_name.lower())
        return True

    def _constant_time_compare(self, a: str, b: str) -> bool:
        """Constant-time string comparison."""
        return hmac.compare_digest(a.encode('utf-8'), b.encode('utf-8'))

    def _check_permission(self, user_id: str, filename: str) -> bool:
        """Check if user has permission to access file."""
        if user_id not in self.user_permissions:
            return False
        # Use same NFKC normalization as everywhere else
        norm_name = self._normalize_filename(filename)
        return norm_name.lower() in self.user_permissions[user_id]

    def read_file(self, user_id: str, filename: str) -> Optional[str]:
        """Read a file from the vault with full security checks."""
        # Rate limiting
        if not self.rate_limiter.check(user_id):
            return None

        # Validate filename (uses NFKC)
        if not self._validate_filename(filename):
            return None

        # Check permission (uses NFKC normalization)
        if not self._check_permission(user_id, filename):
            return None

        # Construct path using NFKC-normalized name
        safe_name = self._normalize_filename(filename)
        full_path = os.path.join(self.base_dir, safe_name)

        # Path traversal protection
        if not self._check_path_safety(full_path):
            return None

        try:
            with open(full_path, 'r') as f:
                return f.read()
        except (IOError, OSError):
            return None

    def write_file(self, user_id: str, filename: str, content: str) -> bool:
        """Write a file to the vault."""
        if not self.rate_limiter.check(user_id):
            return False

        if not self._validate_filename(filename):
            return False

        if not self._check_permission(user_id, filename):
            return False

        safe_name = self._normalize_filename(filename)
        full_path = os.path.join(self.base_dir, safe_name)

        if not self._check_path_safety(full_path):
            return False

        # Limit file size
        if len(content) > 10240:
            return False

        try:
            with open(full_path, 'w') as f:
                f.write(content)
            return True
        except (IOError, OSError):
            return False
